26	export default function jitterLayout(ecModel: GlobalModel) {
27	    ecModel.eachSeriesByType('scatter', function (seriesModel: ScatterSeriesModel) {
28	        const coordSys = seriesModel.coordinateSystem;
29	        if (coordSys
30	            && (coordSys.type === 'cartesian2d' || coordSys.type === 'single')) {
31	            const baseAxis = coordSys.getBaseAxis ? coordSys.getBaseAxis() : null;
32	            const hasJitter = baseAxis && needFixJitter(seriesModel, baseAxis);
33	
34	            if (hasJitter) {
35	                const data = seriesModel.getData();
36	                data.each(function (idx) {
37	                    const dim = baseAxis.dim;
38	                    const orient = (baseAxis as SingleAxis).orient;
39	                    const isSingleY = orient === 'horizontal' && baseAxis.type !== 'category'
40	                        || orient === 'vertical' && baseAxis.type === 'category';
41	                    const layout = data.getItemLayout(idx);
42	                    const rawSize = data.getItemVisual(idx, 'symbolSize');
43	                    const size = rawSize instanceof Array ? (rawSize[1] + rawSize[0]) / 2 : rawSize;
44	
45	                    if (dim === 'y' || dim === 'single' && isSingleY) {
46	                        // x is fixed, and y is floating
47	                        const jittered = fixJitter(
48	                            baseAxis as Axis2D | SingleAxis,
49	                            layout[0],
50	                            layout[1],
51	                            size / 2
52	                        );
53	                        data.setItemLayout(idx, [layout[0], jittered]);
54	                    }
55	                    else if (dim === 'x' || dim === 'single' && !isSingleY) {
56	                        // y is fixed, and x is floating
57	                        const jittered = fixJitter(
58	                            baseAxis as Axis2D | SingleAxis,
59	                            layout[1],
60	                            layout[0],
61	                            size / 2
62	                        );
63	                        data.setItemLayout(idx, [jittered, layout[1]]);
64	                    }
65	                });
66	            }
67	        }
68	    });
69	}
